24	export function getUserId(): string {
25	  let globalConfig = readGlobalConfig();
26	  if (!globalConfig?.id) {
27	    const newId = crypto.randomUUID();
28	    globalConfig = { ...globalConfig, id: newId };
29	    writeGlobalConfig(globalConfig);
30	    return newId;
31	  }
32	
33	  return globalConfig.id;
34	}
