95	/**
96	 * Get the authentication method used for cloud access
97	 * @returns 'api-key' | 'email' | 'none'
98	 */
99	export function getAuthMethod(): 'api-key' | 'email' | 'none' {
100	  const cloudConfig = new CloudConfig();
101	  const hasApiKey = cloudConfig.isEnabled();
102	  const hasEmail = !!getUserEmail();
103	
104	  if (hasApiKey && hasEmail) {
105	    // Both present - API key is the actual auth mechanism
106	    return 'api-key';
107	  }
108	  if (hasApiKey) {
109	    return 'api-key';
110	  }
111	  if (hasEmail) {
112	    // Email without API key - not fully authenticated
113	    // (this shouldn't happen in normal flow but handle it)
114	    return 'email';
115	  }
116	  return 'none';
117	}
