127	/**
128	 * Builds a safe JSON path for use in SQLite json_extract() queries.
129	 *
130	 * SECURITY NOTE: This function uses sql.raw() which is normally unsafe, but is REQUIRED here
131	 * because SQLite's json_extract() function only accepts JSON paths as string literals,
132	 * not as parameterized values.
133	 *
134	 * Safety is ensured through double escaping:
135	 * 1. JSON path characters are escaped (backslashes and double quotes)
136	 * 2. SQL single quotes are escaped using standard SQL escaping ('' for ')
137	 *
138	 * @param field - The JSON field name from user input
139	 * @returns A sql.raw() fragment containing the safely escaped JSON path
140	 */
141	export function buildSafeJsonPath(field: string): ReturnType<typeof sql.raw> {
142	  const jsonPathContent = `$."${escapeJsonPathKey(field)}"`;
143	  // Escape single quotes for SQL string literal (standard SQL escaping)
144	  const sqlSafeJsonPath = jsonPathContent.replace(/'/g, "''");
145	  // sql.raw() is safe here because we've fully escaped the content
146	  return sql.raw(`'${sqlSafeJsonPath}'`);
147	}
